statement:
Call a subsequence of `s` *good* when all three of these hold:

- it is a palindrome (the same read forwards and backwards);
- its length is even;
- no two neighbouring characters in it are equal, with one exception: the two characters in the exact middle (which are always equal).

Return the length of the longest good subsequence of `s`, or `0` when no non-empty good subsequence exists. A subsequence keeps the chosen characters in their original order but need not be contiguous.

validator:
function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 250) return 's has 1 to 250 characters.';
  if (!/^[a-z]+$/.test(s)) return 'Use only lowercase English letters.';
  return null;
}

reference:
function longestPalindromeSubseq(s) {
  const n = s.length;
  const letter = Array.from(s, ch => ch.charCodeAt(0) - 97);
  let prev = Array.from({ length: n }, () => new Array(26).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    const dp = Array.from({ length: n }, () => new Array(26).fill(0));
    for (let j = i + 1; j < n; j++) {
      for (let c = 0; c < 26; c++) {
        dp[j][c] = Math.max(prev[j][c], dp[j - 1][c]);
      }
      if (letter[i] === letter[j]) {
        let inside = 0;
        for (let c = 0; c < 26; c++) {
          if (c !== letter[i]) {
            inside = Math.max(inside, prev[j - 1][c]);
          }
        }
        dp[j][letter[i]] = Math.max(dp[j][letter[i]], inside + 2);
      }
    }
    prev = dp;
  }
  return Math.max(...prev[n - 1]);
}

brute:
function longestPalindromeSubseq(s) {
  // Check every subsequence against the three rules directly.
  let best = 0;
  for (let mask = 1; mask < 1 << s.length; mask++) {
    let t = '';
    for (let i = 0; i < s.length; i++) if (mask >> i & 1) t += s[i];
    if (t.length % 2 !== 0 || t.length <= best) continue;
    if (t !== [...t].reverse().join('')) continue;
    let ok = true;
    for (let k = 0; k + 1 < t.length; k++) if (t[k] === t[k + 1] && k !== t.length / 2 - 1) ok = false;
    if (ok) best = t.length;
  }
  return best;
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, size === 'large' ? 2 + pick(25) : 1 + pick(4));
  const randomText = length => Array.from({ length }, () => letters[pick(letters.length)]).join('');
  const n = size === 'large' ? 200 + pick(51) : 1 + pick(12);
  if (rand() < 0.5) return [randomText(n)];
  // Hide a long palindrome among noise so that large answers appear too.
  const half = randomText(Math.ceil(n / 2));
  const mirrored = (half + [...half].reverse().join('')).split('');
  for (let k = 0; k < mirrored.length; k++) if (rand() < 0.2) mirrored[k] = letters[pick(letters.length)];
  return [mirrored.join('').slice(0, n)];
}
